{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Sampled final-training transitions show weaker positive–negative separation in Industrial_and_Scientific and Electronics: negative margins occur for 24.61% and 27.97% of users, versus 0.94% in Movies_and_TV and 0.47% in CDs_and_Vinyl. These in-sample, two-candidate statistics do not measure validation HR@10 or establish calibrated failure.",
    "Unchanged-history checks pass for all four datasets, but intervention effects and strength are omitted. Reported common support is 1,279/1,280 users for Movies_and_TV and 1,280/1,280 elsewhere; failed matching coverage is not visible, so matched sensitivity comparisons cannot be assessed."
  ],
  "key_implications": [
    "Training separation differs across categories, but neither its magnitude nor embedding cosine values establish generalization, collapse, or recommendation diversity.",
    "Compacted deletion changes content and positions; fixed-slot substitution changes content; permutation preserves the item multiset; none identifies causal history effects.",
    "Dataset identifiers and prospective-pilot metrics are null; temporal matching and explicit-position controls are unavailable, padding-key masking is unverified, and no sensitivity–accuracy relationship or empirical gain is established; selection remains independent macro validation HR@10."
  ],
  "evidence": {
    "headline_metrics": {
      "eligible_users_per_dataset": 1280,
      "mean_margin_movies_industrial_electronics_cds": [10.776, 1.122, 1.009, 19.153],
      "embedding_mean_cosine_movies_industrial_electronics_cds": [0.0719, 0.0176, 0.0042, 0.2092],
      "unchanged_history_checks_passed": 4
    },
    "brief_metric_read": {
      "mean_margin": "Final training target minus one fixed unseen negative; score scales are uncalibrated.",
      "embedding_mean_cosine": "Off-diagonal embedding similarity; does not establish collapse or diversity.",
      "uncertainty": "Bootstrap intervals condition on the fitted model and panel; exclude training-seed variation and adaptive validation reuse."
    }
  }
}
